# mirrorHostConfig 检测 Host 配置不当的问题
mirrorHostConfig = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 使用单一测试域名进行检测
    testHost = "attack.com"

    req = poc.ReplaceHTTPPacketHeader(req, "Host", testHost) // 替换为测试的 Host
    resRaw, reqRaw, err = poc.HTTP(req, poc.https(isHttps))
    if err != nil {
        yakit.Warn(sprintf("%v请求失败！测试域名: %v", url, testHost))
        return
    }

    // 获取响应状态码
    if resRaw == nil {
        yakit.Warn(sprintf("%v响应为空！测试域名: %v", url, testHost))
        return
    }

    header, bodyRaw = str.SplitHTTPHeadersAndBodyFromPacket(resRaw)
    if len(header) == 0 {
        yakit.Warn(sprintf("%v响应头为空！测试域名: %v", url, testHost))
        return
    }

    statusLine = str.ParseStringToLines(header)[0]
    statusParts = str.Split(statusLine, " ")
    if len(statusParts) < 2 {
        yakit.Warn(sprintf("%v状态行格式错误！测试域名: %v", url, testHost))
        return
    }

    statusCode = int(statusParts[1])
    locationHeader = str.Join(header, "Location") // 使用 Join 方法获取 Location 头

    // 只检查301状态码的响应中的Location头
    if statusCode == 301 && locationHeader != "" && testHost in locationHeader {
        yakit.Info(sprintf("%v存在Host头攻击漏洞，状态码: %v", url, statusCode))

        // 构建详细的描述信息
        description = sprintf("Host头攻击可能导致请求被错误路由或信息泄露。服务器在处理%v重定向时未正确验证Host头的值，导致攻击者可以控制重定向目标。\n\n检测到的Location头: %v", statusCode, locationHeader)

        risk.NewRisk(url,
            risk.title(sprintf("%v 存在Host头攻击漏洞", url)),
            risk.titleVerbose(sprintf("检测到Host头攻击漏洞：%v (状态码: %v)", url, statusCode)),
            risk.type("其他"),
            risk.severity("high"),
            risk.request(reqRaw),
            risk.response(resRaw),
            risk.description(description),
            risk.payload(testHost),
            risk.solution("1. 在进行URL重定向时，使用白名单验证目标域名\n2. 避免直接使用用户可控的Host头值\n3. 使用相对路径而不是绝对路径进行重定向\n4. 如果必须使用绝对路径，确保域名部分为硬编码值")
        )

        // 找到漏洞后立即返回，避免重复报告
        return
    }
}

# mirrorHTTPFlow 会镜像所有的流量到这里，包括 .js / .css / .jpg 这类一般会被劫持程序过滤的请求
mirrorHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 调用Host头配置检测
    mirrorHostConfig(isHttps, url, req, rsp, body)
}

# mirrorFilteredHTTPFlow 劫持到的流量为 MITM 自动过滤出的可能和 "业务" 有关的流量，会自动过滤掉 js / css 等流量
mirrorFilteredHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 调用Host头配置检测
    mirrorHostConfig(isHttps, url, req, rsp, body)
}

# mirrorNewWebsite 每新出现一个网站，这个网站的第一个请求，将会在这里被调用！
mirrorNewWebsite = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 调用Host头配置检测
    mirrorHostConfig(isHttps, url, req, rsp, body)
}

# mirrorNewWebsitePath 每新出现一个网站路径，关于这个网站路径的第一个请求，将会在这里被传入回调
mirrorNewWebsitePath = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 调用Host头配置检测
    mirrorHostConfig(isHttps, url, req, rsp, body)
}

# mirrorNewWebsitePathParams 每新出现一个网站路径且带有一些参数，参数通过常见位置和参数名去重，去重的第一个 HTTPFlow 在这里被调用
mirrorNewWebsitePathParams = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    // 调用Host头配置检测
    mirrorHostConfig(isHttps, url, req, rsp, body)
}
